SELECT item_id,payload,payload_bytes,live,settlement_charge_bytes AS settlement_bytes,CAST(json_object('kind',record_kind,'value',json_object('id',item_id,'digest',digest,'acceptanceBound',acceptance_bound,'submitAttempted',json(CASE submit_attempted WHEN 0 THEN 'false' WHEN 1 THEN 'true' ELSE 'null' END),'settlementBytes',settlement_bytes,'cancel',cancel_outcome,'statusKind',status_kind,'version',status_version)) AS TEXT) AS record FROM _fleet_sync_outbox_items ORDER BY item_id;
